INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-card-box', 0, 'lab', 'Карточка с отступами', 'Оформите карточку .card: внутренний отступ не меньше 16px со всех сторон, сплошная рамка толщиной не меньше 1px, ширина не больше 480px, а сама карточка стоит по центру страницы (внешние отступы слева и справа автоматические).', '', 'padding задаёт отступ внутри рамки; border — рамку (нужен стиль, например solid); max-width ограничивает ширину; margin: 0 auto центрирует блок с ограниченной шириной.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-border-box', 1, 'lab', 'Ширина вместе с отступами', 'У колонок .col заданы ширина 300px, padding 20px и рамка 2px (правило уже есть в стилях задания), поэтому на деле они шире 300px. Переключите расчёт так, чтобы ширина включала паддинг и рамку, и сделайте это для всех элементов страницы и их псевдоэлементов — как делают в начале реальных проектов.', '', 'Значение border-box у свойства box-sizing. Чтобы охватить всё сразу, правило пишут для селектора из звёздочки и двух её псевдоэлементов: *, *::before, *::after.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-sizes', 2, 'lab', 'Размеры и пропорции', 'Видеоплеер .video должен занимать всю доступную ширину, но не больше 640px, держать пропорции 16 к 9 и быть не ниже 120px. Превью .thumb (ширина 120px уже задана) должно быть квадратным без указания высоты.', '', 'max-width ограничивает рост, min-height — снизу; aspect-ratio записывается как 16 / 9, для квадрата достаточно 1.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-overflow', 3, 'lab', 'Блок с прокруткой', 'Лог .log выводит много строк. Ограничьте его высоту (от 50px до 200px) и добавьте вертикальную прокрутку, когда строки не помещаются; по горизонтали всё лишнее должно обрезаться.', '', 'max-height задаёт потолок высоты, overflow-y: auto показывает полосу только при необходимости, overflow-x: hidden обрезает лишнее по горизонтали.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-radius-shadow', 4, 'lab', 'Скругление и тень', 'Карточке .card нужны скруглённые углы (радиус от 8px до 24px) и тень. Аватар .avatar (размеры 64 на 64 уже заданы) должен стать кругом без указания радиуса в пикселях.', '', 'border-radius принимает и проценты: 50% на квадрате даёт круг. Тень задаёт box-shadow: смещение по x и y, размытие, цвет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-outline-focus', 5, 'lab', 'Видимый фокус', 'Кто-то отключил обводку фокуса у кнопки .btn: с клавиатуры не видно, где вы находитесь. Верните заметный контур для состояния focus-visible: сплошной, не тоньше 2px, с отступом от границы кнопки не меньше 2px.', '', 'Не нужно возвращать outline всегда: достаточно правила .btn:focus-visible с outline (толщина, стиль solid, цвет) и outline-offset.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-bg-gradient', 6, 'lab', 'Фон с градиентом', 'Оформите шапку .hero отдельными свойствами фона: фоновая картинка background-image — линейный градиент (linear-gradient) между двумя цветами, размер фона cover, расположение по центру, без повторения. Цвет текста — белый.', '', 'Градиент — это фоновая картинка, поэтому он идёт в background-image. Дальше background-size, background-position (center), background-repeat (no-repeat) и color.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-typography', 7, 'lab', 'Читаемый текст', 'Настройте статью .post: шрифты — Verdana, затем Arial, затем общее семейство sans-serif (именно в таком порядке), межстрочный интервал абзацев — числом не меньше 1.4, заголовок h1 по центру и с разрежением букв не меньше 1px.', '', 'font-family перечисляют через запятую, заканчивая общим семейством; line-height удобно задавать числом без единиц; letter-spacing — в px или em.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-links-case', 8, 'lab', 'Ссылки и метки', 'Ссылки меню .link должны быть без подчёркивания, а при наведении — с подчёркиванием. Метка .tag выводится ПРОПИСНЫМИ буквами, хотя в разметке написана строчными.', '', 'text-decoration: none снимает подчёркивание; для наведения нужно правило с :hover. Регистр меняет text-transform.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-ellipsis', 9, 'lab', 'Длинное название в одну строку', 'Название товара .title стоит в узкой колонке (ширина 200px уже задана). Не давайте ему переноситься: пусть остаётся в одну строку, лишнее скрывается, а на конце показывается многоточие.', '', 'Нужна связка из трёх свойств: white-space: nowrap, overflow: hidden и text-overflow: ellipsis. Без любого из них многоточия не будет.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-list-menu', 10, 'lab', 'Список как меню', 'Из маркированного списка .menu сделайте меню: уберите маркеры у пунктов и нулевой внутренний отступ слева, который браузер добавляет по умолчанию.', '', 'list-style: none (или list-style-type: none) убирает маркеры; padding-left: 0 — отступ списка. Свойство list-style-type наследуется, так что достаточно правила для .menu.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-marker', 11, 'lab', 'Свой маркер', 'У списка дел .todo сделайте квадратные маркеры (square), а сам маркер у пунктов покрасьте в #c0392b — текст пунктов должен остаться прежним.', '', 'list-style-type выбирает вид маркера. Цвет маркера меняет псевдоэлемент ::marker у li.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-badge', 12, 'lab', 'Значки в углах карточки', 'Значок .badge должен прижаться к правому верхнему углу карточки .card с отступом 8px от краёв, а значок .sale — к левому нижнему, тоже с отступом 8px. Карточка служит опорной точкой для позиционирования.', '', 'У родителя position: relative — он становится содержащим блоком. У значков position: absolute и отступы через top, right, bottom, left.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-sticky', 13, 'lab', 'Липкая шапка', 'Шапка .top должна прилипать к верхнему краю окна при прокрутке (отступ сверху 0), лежать выше остального содержимого и иметь непрозрачный белый фон (#ffffff), чтобы текст под ней не просвечивал.', '', 'position: sticky работает вместе с top: 0; чтобы шапка была над содержимым, нужен z-index; фон задаёт background-color.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-z-index', 14, 'lab', 'Выпадающее меню поверх', 'Выпадающий список .dropdown прячется под содержимым страницы. Сделайте его абсолютно позиционированным внутри .menu-wrap (опорная точка) и поднимите выше содержимого .content — у него уже задан z-index 2.', '', 'Нужно position: relative у .menu-wrap, position: absolute у .dropdown и z-index больше двух. z-index работает только у позиционированных элементов.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-before', 15, 'lab', 'Метка перед заголовком', 'Перед каждым заголовком .news выводите звёздочку «★» через псевдоэлемент ::before (без изменения разметки) и отодвиньте её от текста: правый внешний отступ не меньше 6px.', '', 'Псевдоэлемент ::before появляется только при заданном content. Текст в content пишется в кавычках: content: "★".', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-display-none', 16, 'lab', 'Скрыть или спрятать', 'Рекламный блок .promo должен полностью исчезнуть из раскладки и не занимать места. А блок .ghost, наоборот, должен остаться на месте и занимать место, но стать невидимым.', '', 'display: none убирает элемент из потока вовсе, visibility: hidden прячет, но место сохраняется.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-margin-collapse', 17, 'lab', 'Отступ вылез наружу', 'Заголовок .title внутри секции .wrap имеет верхний отступ 40px (он уже задан), но этот отступ «вылезает» из секции и сдвигает её саму, вместо того чтобы отодвинуть заголовок. Сделайте секцию контейнером, который не пропускает отступ детей наружу, не добавляя ей рамки и padding.', '', 'Новый контекст форматирования у родителя запрещает схлопывание: display: flow-root. Подойдут и flex- или grid-контейнер.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-fixed-button', 18, 'lab', 'Кнопка «наверх»', 'Кнопка .to-top должна всегда оставаться в правом нижнем углу окна, даже при прокрутке: отступы от правого и нижнего края от 8px до 32px, поверх остального содержимого.', '', 'position: fixed привязывает элемент к окну; координаты задают right и bottom; для слоя нужен z-index.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 18, 'w18-clearfix', 19, 'lab', 'Clearfix для float', 'Картинка .pic обтекается слева (float: left уже задан), поэтому контейнер .clearfix схлопнулся и не охватывает её. Напишите прежний приём clearfix: псевдоэлемент ::after с пустым content, блочным выводом и очисткой обтекания с обеих сторон.', '', 'Правило .clearfix::after { content: ""; display: block; clear: both } — пустой блок в конце, который обязан стоять ниже всех плавающих элементов. Сегодня то же решает display: flow-root.', '{}');
